<?php
namespace App\Features\Vehicles\Repositories;
use App\Features\Vehicles\Models\Vehicle; use Illuminate\Contracts\Pagination\LengthAwarePaginator; use Illuminate\Database\Eloquent\Builder; use Illuminate\Support\Collection;
class VehicleRepository { public function paginate(array $filters,string $tenantId): LengthAwarePaginator { $q=Vehicle::query()->where('tenant_id',$tenantId)->with('customer'); $this->applyFilters($q,$filters); return $q->orderBy($filters['sort']??'created_at',$filters['direction']??'desc')->paginate((int)($filters['per_page']??25)); } public function find(string $id,string $tenantId): Vehicle { return Vehicle::where('tenant_id',$tenantId)->with(['customer','documents','timelineEvents'])->findOrFail($id); } public function create(array $data): Vehicle { return Vehicle::create($data); } public function update(Vehicle $vehicle,array $data): Vehicle { $vehicle->update($data); return $vehicle->refresh()->load(['customer','documents','timelineEvents']); } public function bulkDelete(array $ids,string $tenantId): int { return Vehicle::where('tenant_id',$tenantId)->whereIn('id',$ids)->delete(); } public function bulkUpdate(array $ids,string $tenantId,array $data): int { return Vehicle::where('tenant_id',$tenantId)->whereIn('id',$ids)->update($data); } public function exportQuery(array $filters,string $tenantId): Collection { $q=Vehicle::query()->where('tenant_id',$tenantId)->with('customer'); $this->applyFilters($q,$filters); return $q->orderBy('vehicle_number')->get(); } private function applyFilters(Builder $q,array $f): void { if(!empty($f['search'])){$s=$f['search'];$q->where(fn($w)=>$w->where('vehicle_number','ilike',"%$s%")->orWhere('manufacturer','ilike',"%$s%")->orWhere('model','ilike',"%$s%")->orWhere('chassis_number','ilike',"%$s%")->orWhereHas('customer',fn($c)=>$c->where('first_name','ilike',"%$s%")->orWhere('last_name','ilike',"%$s%")->orWhere('mobile','ilike',"%$s%")));} foreach(['vehicle_type','manufacturer','model','fuel_type','insurance_status','fitness_status','permit_status','tax_status','puc_status','customer_id'] as $key){ if(!empty($f[$key])) $q->where($key,$f[$key]); } } }
